program='''def transform(grid):
    bg=grid[0][0]; H=len(grid); W=len(grid[0])
    unseen={(r,c) for r in range(H) for c in range(W) if grid[r][c]!=bg}
    objects=[]
    while unseen:
        stack=[unseen.pop()]; obj=[]
        while stack:
            r,c=stack.pop(); obj.append((r,c))
            for dr in (-1,0,1):
                for dc in (-1,0,1):
                    q=(r+dr,c+dc)
                    if q in unseen:
                        unseen.remove(q); stack.append(q)
        objects.append(obj)
    objects.sort(key=lambda o:min(c for r,c in o))
    left,right=objects
    line=grid[left[0][0]][left[0][1]]
    l0=min(r for r,c in left); l1=max(r for r,c in left)
    lc0=min(c for r,c in left); lc1=max(c for r,c in left)
    r0=min(r for r,c in right); rc0=min(c for r,c in right)
    h,w=l1-l0+1,lc1-lc0+1
    out=[[bg]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[l0+r][lc0+c]!=bg: out[r][c]=line
    holes={(r,c) for r in range(h) for c in range(w) if out[r][c]==bg}
    while holes:
        seed=holes.pop(); stack=[seed]; comp=[]
        while stack:
            r,c=stack.pop(); comp.append((r,c))
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                q=(r+dr,c+dc)
                if q in holes:
                    holes.remove(q); stack.append(q)
        # The outer background touches the crop boundary.
        if any(r in (0,h-1) or c in (0,w-1) for r,c in comp): continue
        counts={}
        for r,c in comp:
            rr,cc=r0+r,rc0+c
            if 0<=rr<H and 0<=cc<W:
                v=grid[rr][cc]
                if v not in (bg,line): counts[v]=counts.get(v,0)+1
        if counts:
            color=max(counts,key=counts.get)
            for r,c in comp: out[r][c]=color
    return out
'''
